#include <stdio.h>


int main(void)
{
    int left = 0, right = 0, count = 0;
    while (left < right) {
        count++;
        left++;
    }
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int pairs = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = i + 1; j < 4; j++) {
            pairs++;
        }
    }
    printf("%d\n", pairs);
    return 0;
}

